def _parse_isotime(self, timestr):
    """
    Parse the time portion of an ISO string.

    :param timestr:
        The time portion of an ISO string, without a separator

    :return:
        Returns a tuple of ``(hour, minute, second, microsecond, tzinfo)``
    """
    len_str = len(timestr)
    pos = 0
    comps = [0, 0, 0, 0, None]

    if len_str - pos < 2:
        raise ValueError('Minimum length of time component is 2')

    for i in range(0, min(len_str - pos, 2)):
        if timestr[pos + i:pos + i + 1].isdigit():
            continue

        raise ValueError('Invalid time format')

    hour = int(timestr[pos:pos + 2])
    pos += 2

    if hour == 24:
        if pos < len_str and timestr[pos:pos + 1] not in ('Z', '+', '-'):
            raise ValueError('Hour may only be 24 at end of day')
        comps[0] = 0
        comps[1] = 0
        comps[2] = 0
        comps[3] = 0
        return comps + [timedelta(days=1)]
    elif hour > 23:
        raise ValueError('hour must be in 0..23')

    comps[0] = hour

    if pos < len_str and timestr[pos:pos + 1] not in 'Z+-':

        if timestr[pos:pos + 1] in ':':
            pos += 1

        if pos < len_str - 1:

            for i in range(0, min(len_str - pos, 2)):
                if timestr[pos + i:pos + i + 1].isdigit():
                    continue

                raise ValueError('Invalid time format')

            minute = int(timestr[pos:pos + 2])

            if minute not in range(0, 60):
                raise ValueError('minute must be in 0..59')

            comps[1] = minute
            pos += 2

        if pos < len_str and timestr[pos:pos + 1] not in 'Z+-':

            if timestr[pos:pos + 1] in ':':
                pos += 1

            if pos < len_str - 1:

                for i in range(0, min(len_str - pos, 2)):
                    if timestr[pos + i:pos + i + 1].isdigit():
                        continue

                    raise ValueError('Invalid time format')

                second = int(timestr[pos:pos + 2])

                if second not in range(0, 60):
                    raise ValueError('second must be in 0..59')

                comps[2] = second
                pos += 2

            if pos < len_str and timestr[pos:pos + 1] in '.,':
                pos += 1

                microsecond_chars = b''

                for i in range(pos, min(pos + 6, len_str)):
                    if timestr[i:i + 1].isdigit():
                        microsecond_chars += timestr[i:i + 1]
                    else:
                        break

                if len(microsecond_chars) > 0:
                    microsecond_chars += b'0' * (6 - len(microsecond_chars))
                    comps[3] = int(microsecond_chars)
                    pos += len(microsecond_chars) - (6 - len(microsecond_chars))

    if pos < len_str:
        frac, pos = self._parse_isotz(timestr, pos)
        comps[4] = frac

    if pos < len_str:
        raise ValueError('String contains unknown ISO time component: {}'.format(
            timestr[pos:]))

    return comps

