def _parse_isotime(self, timestr):
    # This is adapted from the `parse_time` method in the parser itself.
    len_str = len(timestr)
    pos = 0
    comps = [0, 0, 0, 0]

    for i in range(0, 3):
        if pos >= len_str:
            break

        if i == 0:
            # Hour
            comps[i] = self._parse_two_digits(timestr, pos, 'hour')
            pos += 2
        elif i == 1:
            # Minute
            if timestr[pos:pos + 1] in (b':', b''):
                if timestr[pos:pos + 1] == b':':
                    pos += 1
                comps[i] = self._parse_two_digits(timestr, pos, 'minute')
                pos += 2
        elif i == 2:
            # Second
            if timestr[pos:pos + 1] in (b':', b''):
                if timestr[pos:pos + 1] == b':':
                    pos += 1
                comps[i] = self._parse_two_digits(timestr, pos, 'second')
                pos += 2

    if pos < len_str and timestr[pos:pos + 1] in (b'.', b','):
        pos += 1
        microsecond_chars = b''
        while pos < len_str and timestr[pos:pos + 1].isdigit():
            microsecond_chars += timestr[pos:pos + 1]
            pos += 1

        microsecond_chars = microsecond_chars.ljust(6, b'0')[:6]
        comps[3] = int(microsecond_chars)

    # Handle 24:00:00 case - convert to next day 00:00:00
    if comps[0] == 24:
        if comps[1] != 0 or comps[2] != 0 or comps[3] != 0:
            raise ValueError('Hour is 24, but minutes, seconds, or microseconds are not zero')
        comps[0] = 0
        # Return a special marker to indicate we need to add a day
        return comps + [1]  # The last element (1) indicates to add 1 day

    return comps

